package canteen;
import javax.swing.*;import java.awt.*;
public class HelpAboutFrame extends JFrame {
 public HelpAboutFrame(){AppStyle.setWindowIcon(this);setTitle("PIET | Help & About");setSize(720,590);setLocationRelativeTo(null);JPanel p=AppStyle.page("Help & about");JTextArea text=new JTextArea();text.setEditable(false);text.setLineWrap(true);text.setWrapStyleWord(true);text.setFont(new Font("Segoe UI",Font.PLAIN,14));text.setMargin(new Insets(18,18,18,18));text.setText("PIET CANTEEN BILLING SYSTEM\nVersion 2.0\n\nDesigned & Developed by Kevaram\nPoornima Institute of Engineering & Technology, Jaipur\n\nQUICK HELP\n1. Sign in using an administrator- or staff-created account.\n2. Use New Bill to add available food items, set a percentage discount and choose Cash, UPI or Card.\n3. Review the total and confirm before completing payment. Print the receipt after saving.\n4. Stock is reduced automatically when a bill is completed.\n5. Administrators can manage food, stock, users, GST settings, reports, audit history and database backups.\n6. Staff can create bills, view all orders, check availability and see low-stock notifications.\n\nDATABASE TROUBLESHOOTING\n• Start the MySQL service and ensure piet_canteen_db exists.\n• Run database/01_migration.sql before launching the application.\n• Configure PIET_DB_URL, PIET_DB_USER and PIET_DB_PASSWORD, or update DBConnection.java for your local environment.\n• Ensure the MySQL Connector/J JAR is added to the NetBeans project Libraries.\n• Back up your database before schema changes or restore operations.\n\nDatabase status: "+(DBConnection.isConnected()?"CONNECTED":"NOT CONNECTED")+"\n\nSecurity: passwords are stored using PBKDF2-HMAC-SHA256; access is role-restricted.");p.add(new JScrollPane(text),BorderLayout.CENTER);add(p);}
}
